<?php
require 'auth.php';require_login();require 'db.php';require 'layout.php';
if($_SERVER['REQUEST_METHOD']==='POST'){$amount=(float)($_POST['amount']??0);$type=$_POST['donation_type']??'money';$purpose=trim($_POST['purpose']??'');$items=trim($_POST['item_details']??'');$uid=$_SESSION['user_id'];$s=$conn->prepare("INSERT INTO donations(donor_id,status,amount,donation_date,user_id) VALUES(?,'received',?,CURDATE(),?)");$s->bind_param('idi',$uid,$amount,$uid);$s->execute();$did=$conn->insert_id;$d=$conn->prepare('INSERT INTO donation_details(donation_id,donation_type,purpose,item_details) VALUES(?,?,?,?)');$d->bind_param('isss',$did,$type,$purpose,$items);$d->execute();header('Location: donations.php?msg='.urlencode('Thank you! Donation recorded.'));exit;}
$rows=$conn->query('SELECT d.*,u.full_name,dd.donation_type,dd.purpose,dd.item_details FROM donations d JOIN users u ON d.donor_id=u.user_id LEFT JOIN donation_details dd ON d.donation_id=dd.donation_id ORDER BY d.donation_id DESC');$tot=$conn->query("SELECT COALESCE(SUM(amount),0) total FROM donations WHERE status='received'")->fetch_assoc()['total'];page_top('Donations');
?><div class="section-head"><h1 class="page-title">Donations</h1><span class="tag">Total received: ৳<?=number_format((float)$tot,2)?></span></div><form class="form-card form-grid" method="post"><select name="donation_type"><option value="money">Money</option><option value="food">Food</option><option value="medicine">Medicine</option><option value="supplies">Supplies</option><option value="other">Other</option></select><input type="number" step="0.01" min="0" name="amount" placeholder="Amount (0 for item donations)"><input class="full" name="purpose" placeholder="Purpose"><textarea class="full" name="item_details" placeholder="Item details (for non-money donations)"></textarea><button class="btn full">Record Donation ❤️</button></form><div class="section-head"><h2>Donation history</h2></div><div class="table-wrap"><table><tr><th>ID</th><th>Donor</th><th>Type</th><th>Amount</th><th>Purpose</th><th>Date</th><th>Status</th></tr><?php while($r=$rows->fetch_assoc()):?><tr><td>#<?=$r['donation_id']?></td><td><?=h($r['full_name'])?></td><td><?=h($r['donation_type']??'money')?></td><td>৳<?=number_format((float)$r['amount'],2)?></td><td><?=h($r['purpose']??'')?></td><td><?=h($r['donation_date'])?></td><td><span class="tag"><?=h($r['status'])?></span></td></tr><?php endwhile;?></table></div><?php page_bottom(); ?>
